// 고정 원문 VM 및 독립 배열 oracle로 대조한 벡터. native 실행은 하지 않았다.
use super::*;
use std::collections::BTreeMap;
struct Fixture(BTreeMap<(u64,u8),u64>);
impl Memory for Fixture{fn read(&mut self,a:u64,w:u8)->Result<u64,&'static str>{self.0.get(&(a,w)).copied().ok_or("MISSING_FIELD")}}
#[test]fn no_write(){
let mut m=Fixture([((100728840u64,8u8),1u64),((100794376u64,8u8),2u64),((100728832u64,8u8),0u64),((100794368u64,8u8),100859904u64),((100859904u64,8u8),0u64),((100859912u64,8u8),18446744073709551615u64)].into_iter().collect());let e=evaluate([100728832u64,100728840u64,100794368u64,3735928559u64],&mut m).unwrap();assert_eq!(e.expected,0u64);assert_eq!(e.mask,u64::MAX);assert_eq!(e.output_fields,vec![]);
let mut m=Fixture([((100728848u64,8u8),2u64),((100794376u64,8u8),3u64),((100728840u64,8u8),1u64),((100794368u64,8u8),100859904u64),((100859912u64,8u8),18446744073709551615u64),((100859920u64,8u8),18446744073709551614u64)].into_iter().collect());let e=evaluate([100728832u64,100728848u64,100794368u64,3735928559u64],&mut m).unwrap();assert_eq!(e.expected,1u64);assert_eq!(e.mask,u64::MAX);assert_eq!(e.output_fields,vec![]);
let mut m=Fixture([((100728904u64,8u8),9u64),((100794376u64,8u8),10u64),((100728896u64,8u8),8u64),((100794368u64,8u8),100859904u64),((100859968u64,8u8),18446744073709551608u64),((100859976u64,8u8),18446744073709551607u64)].into_iter().collect());let e=evaluate([100728832u64,100728904u64,100794368u64,3735928559u64],&mut m).unwrap();assert_eq!(e.expected,8u64);assert_eq!(e.mask,u64::MAX);assert_eq!(e.output_fields,vec![]);
let mut m=Fixture([((100728984u64,8u8),19u64),((100794376u64,8u8),20u64),((100728976u64,8u8),18u64),((100794368u64,8u8),100859904u64),((100860048u64,8u8),18446744073709551598u64),((100860056u64,8u8),18446744073709551597u64)].into_iter().collect());let e=evaluate([100728832u64,100728984u64,100794368u64,3735928559u64],&mut m).unwrap();assert_eq!(e.expected,18u64);assert_eq!(e.mask,u64::MAX);assert_eq!(e.output_fields,vec![]);
}
